namespace Demo.Demos.Quiz;
public sealed class StoredQuizProgress { public string FormatVersion { get; init; } = "3.0"; public string SourceId { get; init; } = string.Empty; public string? LastDocumentId { get; init; } public string? LastDocumentHash { get; init; } public IReadOnlyCollection<StoredQuestionProgress> Questions { get; init; } = []; }
public sealed class StoredQuestionProgress { public string QuestionId { get; init; } = string.Empty; public string ContentHash { get; init; } = string.Empty; public int ConsecutiveCorrectCount { get; init; } public DateTime? LastAnsweredAt { get; init; } public DateTime FirstSeenAtUtc { get; init; } public DateTime LastSeenAtUtc { get; init; } }
public sealed class QuizSynchronizationResult { public int PreservedQuestions { get; init; } public int ResetQuestions { get; init; } public int AddedQuestions { get; init; } public int RemovedQuestions { get; init; } public int ReidentifiedQuestions { get; init; } public bool HasChanges => ResetQuestions + AddedQuestions + RemovedQuestions + ReidentifiedQuestions > 0; }
